<?php
namespace xdecaro\Component\Organizations\Administrator\Service;
defined('_JEXEC') or die;use Joomla\CMS\Factory;use Joomla\Database\DatabaseInterface;use Joomla\Database\ParameterType;use RuntimeException;
final class OrganizationProviderService{public function __construct(private DatabaseInterface $db,private CoreIntegrationService $core){}public function getOrganization(int|string $id,bool $sensitive=false):?array{$this->auth($sensitive);$q=$this->db->getQuery(true)->select($this->columns($sensitive))->from($this->db->quoteName('#__xdecaroorganizations_organizations','o'))->where($this->db->quoteName('o.state').' >= 0');if(is_int($id)||ctype_digit((string)$id)){$n=(int)$id;$q->where($this->db->quoteName('o.id').' = :id')->bind(':id',$n,ParameterType::INTEGER);}else{$uuid=trim((string)$id);$q->where($this->db->quoteName('o.uuid').' = :uuid')->bind(':uuid',$uuid);}$r=$this->db->setQuery($q,0,1)->loadAssoc();if(!$r)return null;$r['entity_reference']=$this->core->createEntityReference((int)$r['id'])->toArray();return $r;}public function searchOrganizations(array $filters=[],int $limit=50,bool $sensitive=false):array{$this->auth($sensitive);$limit=max(1,min(200,$limit));$q=$this->db->getQuery(true)->select($this->columns($sensitive))->from($this->db->quoteName('#__xdecaroorganizations_organizations','o'))->where($this->db->quoteName('o.state').' = 1')->order($this->db->quoteName('o.name').' ASC');$s=trim((string)($filters['search']??''));if($s!==''){$like='%'.str_replace(' ','%',$s).'%';$q->where('('.$this->db->quoteName('o.name').' LIKE :s1 OR '.$this->db->quoteName('o.code').' LIKE :s2 OR '.$this->db->quoteName('o.email').' LIKE :s3)')->bind(':s1',$like)->bind(':s2',$like)->bind(':s3',$like);}if(!empty($filters['type'])){$type=(string)$filters['type'];$q->where($this->db->quoteName('o.type').' = :type')->bind(':type',$type);}if(array_key_exists('parent_id',$filters)){$parent=(int)$filters['parent_id'];if($parent>0)$q->where($this->db->quoteName('o.parent_id').' = :parent')->bind(':parent',$parent,ParameterType::INTEGER);else$q->where($this->db->quoteName('o.parent_id').' IS NULL');}return array_values((array)$this->db->setQuery($q,0,$limit)->loadAssocList());}public function getChildren(int $id,int $limit=100):array{return $this->searchOrganizations(['parent_id'=>$id],$limit,false);}private function columns(bool $s):array{$c=['o.id','o.uuid','o.name','o.legal_name','o.code','o.type','o.parent_id','o.email','o.phone','o.website','o.logo','o.state','o.access','o.language'];if($s)$c=array_merge($c,['o.vat_id','o.tax_identifier','o.pec_email','o.address_line','o.postal_code','o.city','o.region','o.country_code','o.notes']);return $c;}private function auth(bool $s):void{$u=Factory::getApplication()->getIdentity();if(!$u->authorise('core.manage',CoreIntegrationService::COMPONENT)&&!$u->authorise('core.admin',CoreIntegrationService::COMPONENT))throw new RuntimeException('Not authorised to query Organizations.',403);if($s&&!$u->authorise('organizations.view_sensitive',CoreIntegrationService::COMPONENT)&&!$u->authorise('core.admin',CoreIntegrationService::COMPONENT))throw new RuntimeException('Not authorised to query sensitive organization fields.',403);}}
